"""
Strategy Interface and Implementations.

This module defines how trading decisions are made.
"""

from abc import ABC, abstractmethod
from typing import List, Dict, Any
from dataclasses import dataclass

@dataclass
class TradeSignal:
    """Signal generated by a strategy."""
    symbol: str
    action: str              # 'buy' or 'sell'
    quantity: float
    price_limit: float = 0.0 # Optional limit price
    
    # Metadata for options
    strike: float = 0.0
    expiry: str = ""
    option_type: str = ""    # 'call' or 'put'

class BaseStrategy(ABC):
    """Abstract base class for all strategies."""
    
    @abstractmethod
    def generate_signals(self, portfolio, market_data) -> List[TradeSignal]:
        """
        Core logic: Look at market, decide what to trade.
        
        Args:
            portfolio: Current Portfolio object (to see cash/positions)
            market_data: Current market snapshot
            
        Returns:
            List of TradeSignal objects
        """
        pass

